#include "exotic/cognition/agent_store.hpp"
#include "exotic/cognition/intention.hpp"
#include <cassert>
#include <cstdio>
int main(){const char*db="intention_test.sqlite";std::remove(db);exotic::cognition::AgentStore store(db);store.initialize();exotic::cognition::IntentionManager m(store);exotic::cognition::VolitionDecision d{exotic::cognition::VolitionOutcome::Choose,"inspect","Inspect because evidence is incomplete",0.72};auto c=m.record_choice("Investigate anomaly",d,"2026-09-09T03:40:00Z");auto i=m.propose_intention(c,0.7,"Worth considering, not yet a commitment");assert(i.state=="tentative");assert(m.intentions().front().state=="tentative");assert(m.commit(i.id,"I choose to make this durable"));assert(m.intentions().front().state=="committed");assert(m.suspend(i.id,"New evidence suggests waiting"));assert(m.intentions().front().state=="suspended");assert(m.abandon(i.id,"No longer worth pursuing"));assert(m.intentions().front().state=="abandoned");exotic::cognition::VolitionDecision d2{exotic::cognition::VolitionOutcome::DoNothing,"","No option is worth committing to",0.1};auto c2=m.record_choice("Same anomaly",d2,"2026-09-09T03:41:00Z",c.id);assert(c2.supersedes==c.id);assert(m.choices().size()==2);assert(m.intentions().size()==1);std::remove(db);std::remove("intention_test.sqlite-wal");std::remove("intention_test.sqlite-shm");return 0;}
